// Local-only hierarchy workspace. Raw states remain independent of reconstructed nodes.
const groups=Model.groups, baseRender=render,baseTree=renderTree,baseEditor=editor,baseCheck=check;
let categoryFilter='all',nodeSelection=null,expanded=new Set(['root','reaction','combat','noncombat','combat_select']),lastGraph=[];
try{const newer=localStorage.getItem('ashen-tree-v2');if(newer)data=JSON.parse(newer);else{localStorage.setItem('ashen-tree-v1-backup',JSON.stringify(data));data=Model.migrate(data)}}catch{data=Model.migrate(data)}
for(const m of data.monsters)if(!data.trees[m])data.trees[m]=Model.skeleton();
function treeNodes(){return data.trees[monster]}
save=function(){try{localStorage.setItem('ashen-tree-v2',JSON.stringify(data));$('#saved').textContent='● v2 已保存至本机'}catch{toast('本机存储失败，请导出备份')}};
const catTitle=id=>groups.find(g=>g[0]===id)?.[1]||'通用控制';
const oldVisible=visible;visible=function(){return oldVisible().filter(s=>categoryFilter==='all'||s.category===categoryFilter)};
const toolbar=document.createElement('div');toolbar.id='categories';toolbar.className='categories';$('.canvasbar').before(toolbar);
$('#add').insertAdjacentHTML('afterend','<button class="add" id="newNode">＋ 新增行为树节点</button>');
$('.version').innerHTML='本地重构 <b>v2.0</b>';$('.heading h1').textContent='原始线索，重构为决策。';$('.heading p').textContent='原始状态 → 行为分类 → 行为树 · 示例规则，待实测验证';$('.inspector h2').textContent='原始状态 / 节点检查器';
function layoutNodes(){let row=0;const nodes=treeNodes();function walk(n,depth,path=new Set()){if(path.has(n.id))return;path=new Set(path).add(n.id);n.x=40+depth*245;n.y=30+(row++)*112;for(const c of nodes.filter(c=>c.parent===n.id).sort((a,b)=>b.priority-a.priority||a.id.localeCompare(b.id)))walk(c,depth+1,path)}walk(nodes.find(n=>n.id==='root'),0)}
for(let m of data.monsters){let old=monster;monster=m;if(treeNodes().some(n=>!Number.isFinite(n.x)))layoutNodes();monster=old}
check=function(){let e=[];for(const m of data.monsters){const nodes=data.trees[m]||[];for(const n of nodes){let seen=new Set([n.id]),p=n.parent;if(n.id!=='root'&&!nodes.some(x=>x.id===p))e.push(n.name+'：父节点不存在');while(p){if(seen.has(p)){e.push(n.name+'：父子循环');break}seen.add(p);p=nodes.find(x=>x.id===p)?.parent}if(['动作','条件'].includes(n.type)&&nodes.some(x=>x.parent===n.id))e.push(n.name+'：叶节点不能有子节点');if(['选择器','顺序器'].includes(n.type)&&!nodes.some(x=>x.parent===n.id))e.push(n.name+'：控制节点为空');for(const id of n.sourceIds||[])if(!data.states.some(s=>s.id===id&&s.monster===m))e.push(n.name+'：原始状态引用无效')}for(const s of data.states.filter(s=>s.monster===m))for(let id of (s.mutex+','+s.transitions).split(',').filter(Boolean))if(!data.states.some(x=>x.monster===m&&x.id===id))e.push(s.name+'：状态引用无效 '+id)}return [...new Set(e)]};
function graphNodes(){const nodes=treeNodes(),keep=new Set();if(categoryFilter!=='all'){for(let n of nodes.filter(n=>n.category===categoryFilter)){let cur=n,seen=new Set();while(cur&&!seen.has(cur.id)){seen.add(cur.id);keep.add(cur.id);cur=nodes.find(x=>x.id===cur.parent)}}return nodes.filter(n=>keep.has(n.id))}function shown(n){if(n.id==='root')return true;let p=nodes.find(x=>x.id===n.parent);return p&&expanded.has(p.id)&&shown(p)}return nodes.filter(shown)}
renderTree=function(){let a=graphNodes();lastGraph=a;const positions=new Map();let rows=0;for(let n of a){let depth=0,p=n.parent,seen=new Set([n.id]);while(p&&!seen.has(p)){seen.add(p);depth++;p=treeNodes().find(x=>x.id===p)?.parent}positions.set(n.id,{x:n.customX??30+depth*245,y:n.customY??25+(rows++)*110})}const width=Math.max(1500,...[...positions.values()].map(p=>p.x+230)),height=Math.max(1000,...[...positions.values()].map(p=>p.y+130));$('#tree').style.width=width+'px';$('#tree').style.height=height+'px';$('#lines').setAttribute('width',width);$('#lines').setAttribute('height',height);$('#lines').style.width=width+'px';$('#lines').style.height=height+'px';$('#nodes').innerHTML=a.map(n=>{let p=positions.get(n.id),kids=treeNodes().filter(c=>c.parent===n.id).length;return `<div class="node ${n.id===nodeSelection?'selected':''} kind-${n.type}" data-node="${esc(n.id)}" style="left:${p.x}px;top:${p.y}px"><strong>${n.type==='选择器'?'?':n.type==='顺序器'?'→':n.type==='条件'?'◇':'▸'} ${esc(n.name)}</strong><small>${esc(n.type)} · ${esc(catTitle(n.category))}</small><div class="meta">P${n.priority} · 关联 ${n.sourceIds.length} 原始状态 ${kids?`<button class="fold" data-fold="${esc(n.id)}">${expanded.has(n.id)?'−':'＋'} ${kids}</button>`:''}</div></div>`}).join('');$('#lines').innerHTML=a.map(n=>{let p=positions.get(n.parent),q=positions.get(n.id);return p?`<path d="M${p.x+181} ${p.y+45} C${p.x+220} ${p.y+45},${q.x-40} ${q.y+45},${q.x} ${q.y+45}" fill="none" stroke="#69755b"/>`:''}).join('');document.querySelectorAll('[data-fold]').forEach(b=>b.onclick=e=>{e.stopPropagation();const id=b.dataset.fold;expanded.has(id)?expanded.delete(id):expanded.add(id);renderTree()});document.querySelectorAll('[data-node]').forEach(el=>{el.onpointerdown=e=>{if(e.target.closest('button'))return;e.stopPropagation();let n=treeNodes().find(n=>n.id===el.dataset.node),p=positions.get(n.id),sx=e.clientX,sy=e.clientY,moved=false;el.setPointerCapture(e.pointerId);el.onpointermove=v=>{if(Math.abs(v.clientX-sx)+Math.abs(v.clientY-sy)>5)moved=true;if(moved){n.customX=Math.max(0,p.x+(v.clientX-sx)/zoom);n.customY=Math.max(0,p.y+(v.clientY-sy)/zoom);el.style.left=n.customX+'px';el.style.top=n.customY+'px'}};el.onpointerup=()=>{el.onpointermove=null;if(!moved)nodeSelection=n.id;save();render()}}});setZoom()};
function field(k,title,value,area=false){return `<label>${title}</label>${area?`<textarea name="${k}">${esc(value)}</textarea>`:`<input name="${k}" value="${esc(value)}">`}`}
editor=function(){if(!nodeSelection){baseEditor();const form=$('#form');if(!form)return;const oldSubmit=form.onsubmit;const original=form.querySelector('[name=parent]');original.closest('select').previousElementSibling.textContent='旧版父节点（仅保留追溯）';original.disabled=true;form.insertAdjacentHTML('afterbegin',`<p class="hint">原始资料层：以下条件和状态转移仅记录原文。执行推演使用独立的行为树节点。</p><label>行为分类</label><select name="category">${groups.map(g=>`<option value="${g[0]}" ${current().category===g[0]?'selected':''}>${g[1]}</option>`).join('')}</select>`);form.onsubmit=e=>{e.preventDefault();const s=current(),v=Object.fromEntries(new FormData(form));v.priority=Number(v.priority);Object.assign(s,v);data.log.push({at:new Date().toLocaleString('zh-CN'),name:s.name,text:'原始状态编辑 · '+s.status});save();render();toast('原始资料已保存')};return}const n=treeNodes().find(n=>n.id===nodeSelection);if(!n){nodeSelection=null;return baseEditor()}$('#editor').innerHTML=`<span class="badge">重构节点 · ${esc(n.id)}</span><p class="hint">行为树层：节点可关联多个原始状态。根选择器每 Tick 重评优先级；顺序器记住当前动作，持续检查前置条件。</p><form id="nodeForm">${field('name','节点名称',n.name)}<label>节点类型</label><select name="type" ${n.id==='root'?'disabled':''}>${opts(['选择器','顺序器','条件','动作'],n.type)}</select><label>行为分类</label><select name="category"><option value="all">通用控制</option>${groups.map(g=>`<option value="${g[0]}" ${n.category===g[0]?'selected':''}>${g[1]}</option>`).join('')}</select><label>父节点（仅控制节点可接子节点）</label><select name="parent" ${n.id==='root'?'disabled':''}>${treeNodes().filter(x=>x.id!==n.id&&['选择器','顺序器'].includes(x.type)).map(x=>`<option value="${esc(x.id)}" ${n.parent===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>${field('priority','优先级 / 子节点执行顺序（高者先）',n.priority)}${n.type==='条件'?field('condition','条件表达式',n.condition,true):''}${n.type==='动作'?`<label><input style="width:auto" type="checkbox" name="instant" ${n.instant?'checked':''}> 即时完成动作</label><p class="hint">否则返回 RUNNING，等待“当前动作完成”事件。高优先级分支抢占时调用 OnAbort / CancelAbility。</p>`:''}<label>关联原始状态（可多选）</label><select name="sourceIds" multiple size="6">${data.states.filter(s=>s.monster===monster).map(s=>`<option value="${esc(s.id)}" ${n.sourceIds.includes(s.id)?'selected':''}>${esc(s.id+' · '+s.name)}</option>`).join('')}</select>${field('note','重构依据 / Unreal Engine / GAS / Lua 映射说明',n.note,true)}<button class="gold">保存重构节点</button></form><button id="nodeRemove" style="margin-top:12px">删除叶节点</button>`;$('#nodeForm').onsubmit=e=>{e.preventDefault();const before=structuredClone(n),fd=new FormData(e.target);Object.assign(n,Object.fromEntries(fd));n.sourceIds=fd.getAll('sourceIds');n.priority=Number(fd.get('priority'));n.instant=fd.has('instant');if(!Number.isFinite(n.priority)||check().some(x=>x.startsWith(n.name+'：')&&!x.includes('控制节点为空'))){Object.assign(n,before);toast('无法保存：检查空控制节点、循环或叶节点子项');return}data.log.push({at:new Date().toLocaleString('zh-CN'),name:n.name,text:'行为树节点已编辑；关联 '+n.sourceIds.join(',')});save();render();toast('重构节点已保存')};$('#nodeRemove').onclick=()=>{if(n.id==='root'||treeNodes().some(c=>c.parent===n.id)){toast('请先移动或删除子节点；根节点不可删除');return}data.trees[monster]=treeNodes().filter(x=>x.id!==n.id);nodeSelection=null;save();render()}};
const oldSelect=select;select=function(id){nodeSelection=null;oldSelect(id)};
render=function(){baseRender();$('#categories').innerHTML=`<button data-cat="all" class="${categoryFilter==='all'?'gold':''}">整体决策</button>`+groups.map(g=>`<button data-cat="${g[0]}" class="${categoryFilter===g[0]?'gold':''}" title="${g[2]}">${g[1]} <small>${data.states.filter(s=>s.monster===monster&&s.category===g[0]).length}</small></button>`).join('');document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{categoryFilter=b.dataset.cat;nodeSelection=null;panX=panY=0;render()});$('#viewtitle').textContent=monster+' / '+(categoryFilter==='all'?'整体决策':catTitle(categoryFilter));$('#foot').textContent='选择器：择一 · 顺序器：依次 · 条件：判断 · 动作：执行';$('#count').textContent=visible().length;};
$('#newNode').onclick=()=>{const parent=nodeSelection&&['选择器','顺序器'].includes(treeNodes().find(n=>n.id===nodeSelection)?.type)?nodeSelection:'root';let n={id:'n'+Date.now(),name:'新动作',type:'动作',category:categoryFilter,parent,priority:0,sourceIds:[],condition:'true',note:'',instant:false};treeNodes().push(n);expanded.add(parent);nodeSelection=n.id;save();render()};
const oldAdd=$('#add').onclick;$('#add').onclick=()=>{nodeSelection=null;oldAdd();current().category=categoryFilter==='all'?'peace':categoryFilter;save();render()};$('#layout').onclick=()=>{treeNodes().forEach(n=>{delete n.customX;delete n.customY});panX=panY=0;save();render()};
const oldTable=renderTable;renderTable=function(a){oldTable(a);$('#table').insertAdjacentHTML('afterbegin','<p class="hint">原始状态表：分类只是整理标签，不会覆盖原始条件。点击行查看完整字段。JSON 与 CSV 保留原文。</p>')};
renderReview=function(){$('#review').innerHTML=`<div class="review-card"><b>三层结构与执行约定</b><p>① 原始状态：名称、条件、互斥与转移原样留档。<br>② 行为分类：生命周期、强制反应、目标、阶段、防御、距离、攻击、非战斗。<br>③ 重构行为树：独立节点通过 sourceIds 关联原始状态，可多对多映射。</p><p>生命周期 FSM 与行为树协作：出生完成后设置 spawned，战斗意图由 combatIntent 输入，死亡与强制反应优先于战斗。示例不自动冒充 DS3 逻辑。</p></div><div class="review-card"><b>结构检查 · ${check().length} 项</b><p>${check().map(esc).join('<br>')||'父子关系、控制节点、叶节点和原始状态引用检查通过。'}</p></div><div class="review-card"><b>待验证映射</b><p>${data.states.filter(s=>s.monster===monster&&!treeNodes().some(n=>n.sourceIds.includes(s.id))).length} 个原始状态尚未关联重构节点。没有凭名称自动确认映射。</p></div>`+data.log.slice(-50).reverse().map(l=>`<div class="review-card"><b>${esc(l.at)} · ${esc(l.name)}</b><p style="white-space:pre-wrap">${esc(l.text)}</p></div>`).join('')};
$('#simulate').onclick=()=>{let memory={},tickNo=0;const booleans={spawned:['出生完成',true],combatIntent:['有战斗意图',true],targetVisible:['目标可见',true],executed:['被处决',false],staggered:['韧性耗尽',false],guardBroken:['已破防',false],knockedBack:['被击退',false],phasePending:['待切换阶段',false],threat:['受到威胁',false],heavyReady:['重攻击可用',false],outsideHome:['离开归位范围',false],suspicious:['有可疑目标',false],patrolEnabled:['允许巡逻',true]};modal('<h2>行为树逐 Tick 推演</h2><p>执行完整怪物行为树，显示筛选不改变执行结果。动作等待完成事件；未识别条件返回 UNKNOWN。</p><div class="pair"><div><label>HP<input id="hp2" type="number" value="100"></label></div><div><label>距离<input id="dist2" type="number" value="2"></label></div></div><div class="simChecks">'+Object.entries(booleans).map(([k,[title,v]])=>`<label><input type="checkbox" id="ctx_${k}" ${v?'checked':''}> ${title}</label>`).join('')+'</div><button id="tick2">推进一个 Tick</button><button id="done2">当前动作完成 → Tick</button><button id="reset2">清空运行状态</button><div id="trace2" class="trace"></div>');const run=done=>{const ctx={hp:Number($('#hp2').value),distance:Number($('#dist2').value),animationEnd:done};for(const k in booleans)ctx[k]=$('#ctx_'+k).checked;const prior=memory.active;let r=BT.tick(treeNodes(),ctx,memory);if(done&&prior==='spawn_a0'&&r.status==='SUCCESS')$('#ctx_spawned').checked=true;const title=++tickNo+' · '+({SUCCESS:'成功',FAILURE:'失败',RUNNING:'运行中',UNKNOWN:'待验证'}[r.status]);$('#trace2').innerHTML='<b>'+title+'</b><p>活动动作：'+esc(treeNodes().find(n=>n.id===r.active)?.name||'无')+'</p><pre>'+r.trace.map(esc).join('\n')+'</pre>';data.log.push({at:new Date().toLocaleString('zh-CN'),name:'行为树推演 · '+title,text:JSON.stringify(ctx)+'\n'+r.trace.join('\n')});save();renderReview()};$('#tick2').onclick=()=>run(false);$('#done2').onclick=()=>run(true);$('#reset2').onclick=()=>{memory={};tickNo=0;$('#trace2').textContent='运行状态已重置；Blackboard 输入保留。'}};
const legacyExport=$('#export').onclick;$('#export').onclick=()=>{legacyExport();$('#mdout').onclick=()=>download('Codex-行为树-v2.md','# 怪物 AI 重构说明\n\n仅本地处理，禁止 Sites 或云端上传。\n\n原始资料 states 与重构行为树 trees 分离，sourceIds 为多对多来源映射。legacyTree 保留旧版父子关系。所有示例规则待验证，不代表 DS3 实测结论。\n\n执行约定：选择器 priority 降序，遇 SUCCESS / RUNNING 停止；顺序器按 priority 顺序执行并记忆运行位置，每 Tick 重查前置条件。条件为 true/false 或 Blackboard 字段与数值/布尔比较，支持 &&；未知表达式返回 UNKNOWN 并阻止猜测执行。异步动作返回 RUNNING，当前动作完成事件后返回 SUCCESS。每 Tick 根选择器重评，可抢占低优先动作；中断需要 OnAbort / GAS CancelAbility / Lua 清理回调。生命周期 FSM 提供 spawned、hp、combatIntent 等输入。推演不执行游戏动画，不自动判断原始自由文本退出条件，原始互斥与转移不直接作为 BT 连接。实现前需验证来源并映射条件、退出和互斥。\n\n```json\n'+JSON.stringify(data,null,2)+'\n```','text/markdown');$('#svgout').onclick=()=>{const els=[...document.querySelectorAll('[data-node]')],w=Math.max(800,...els.map(el=>parseFloat(el.style.left)+230)),h=Math.max(300,...els.map(el=>parseFloat(el.style.top)+130));let cards=els.map(el=>{let n=treeNodes().find(n=>n.id===el.dataset.node),x=parseFloat(el.style.left),y=parseFloat(el.style.top);return `<g><rect x="${x}" y="${y}" width="181" height="94" rx="6" fill="#202a21" stroke="#bda777"/><text x="${x+10}" y="${y+28}" fill="#eee" font-size="12">${esc(n.name)}</text><text x="${x+10}" y="${y+53}" fill="#bda777" font-size="10">${esc(n.type)} / P${n.priority}</text></g>`}).join('');download('行为树-v2.svg',`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}"><rect width="100%" height="100%" fill="#121914"/>${$('#lines').innerHTML}${cards}</svg>`,'image/svg+xml')};$('#csvout').onclick=()=>{let keys=['id','monster','category','name','originalName','trigger','priority','entry','exit','mutex','transitions','phase','distance','status','raw','notes'];download('原始状态表-v2.csv',[keys,...data.states.map(s=>keys.map(k=>s[k]))].map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv')}};
$('#file').onchange=async e=>{try{let next=JSON.parse((await e.target.files[0].text()).replace(/^\uFEFF/,''));if(![1,2].includes(next.schemaVersion)||!Array.isArray(next.states)||!Array.isArray(next.monsters)||!next.monsters.length||next.states.length>2000)throw Error('档案格式无效，请使用导出的 JSON 模板');for(const s of next.states){if(!s.id||!s.name||!next.monsters.includes(s.monster))throw Error('原始状态缺少 ID、名称或怪物');for(const k of ['originalName','trigger','entry','exit','mutex','transitions','raw','notes','phase','distance','status'])if(typeof s[k]!=='string')throw Error('缺少原始字段 '+k)}if(new Set(next.states.map(s=>s.id)).size!==next.states.length)throw Error('原始状态 ID 重复');next=Model.migrate(next);for(const m of next.monsters){const ns=next.trees?.[m];if(!Array.isArray(ns)||ns.length>2000||ns.filter(n=>n.id==='root').length!==1||new Set(ns.map(n=>n.id)).size!==ns.length)throw Error('行为树根节点或 ID 无效');for(const n of ns)if(!['选择器','顺序器','条件','动作'].includes(n.type)||!Number.isFinite(n.priority)||typeof n.name!=='string'||typeof n.parent!=='string'||typeof n.condition!=='string'||!Array.isArray(n.sourceIds))throw Error('行为树节点字段无效')}const before=data;data=next;let errors=check();data=before;if(errors.length)throw Error(errors[0]);if(!confirm('替换当前档案？将先在本机保留导入前备份。'))return;localStorage.setItem('ashen-tree-before-import',JSON.stringify(data));data=next;data.log||=[];monster=data.monsters[0];selected=data.states[0]?.id;nodeSelection=null;categoryFilter='all';save();render();toast('导入完成')}catch(err){toast('导入失败：'+err.message)}e.target.value=''};
save();render();
